/**
 * Generate the typed locale registry for main and renderer builds.
 * Owned by shared localization. Namespace filenames are the source of truth.
 */
import { readdir, readFile, writeFile } from 'node:fs/promises';
import { fileURLToPath, URL } from 'node:url';

const shared = new URL('../src/shared/', import.meta.url);
const languages = ['en', 'zh-Hant', 'ja'];
const namespaces = (await readdir(new URL('locales/en/', shared)))
  .filter(name => name.endsWith('.json')).sort();
const lines = [
  '/** Generated by scripts/generate-locales.mjs. Edit the locale JSON files instead. */',
];
for (const [localeIndex, language] of languages.entries()) {
  const files = (await readdir(new URL(`locales/${language}/`, shared)))
    .filter(name => name.endsWith('.json')).sort();
  if (JSON.stringify(files) !== JSON.stringify(namespaces)) {
    throw new Error(`Locale namespaces differ for ${language}`);
  }
  for (const [index, name] of namespaces.entries()) {
    const catalog = JSON.parse(await readFile(new URL(`locales/${language}/${name}`, shared), 'utf8'));
    if (!catalog || Array.isArray(catalog) || typeof catalog !== 'object' ||
        !Object.values(catalog).every(value => typeof value === 'string')) {
      throw new Error(`Expected a flat string catalog at ${language}/${name}`);
    }
    lines.push(`import catalog${localeIndex}_${index} from './locales/${language}/${name}';`);
  }
}
lines.push('export const catalogs = {');
for (const [localeIndex, language] of languages.entries()) {
  lines.push(`  '${language}': {`);
  for (const [index, name] of namespaces.entries()) {
    lines.push(`    ${JSON.stringify(name.slice(0, -5))}: catalog${localeIndex}_${index},`);
  }
  lines.push('  },');
}
lines.push('};', '');
const target = new URL('locales.generated.ts', shared);
const output = lines.join('\n');
let previous;
try { previous = await readFile(target, 'utf8'); } catch (error) {
  if (error.code !== 'ENOENT') throw error;
}
if (previous !== output) await writeFile(target, output);
console.log(`Locale registry ready at ${fileURLToPath(target)} (${namespaces.length} namespaces).`);

// Keep recovery text available even when the renderer module cannot start.
const htmlPath = new URL('../src/renderer/index.html', import.meta.url);
const html = await readFile(htmlPath, 'utf8');
const escapeHtml = value => value.replaceAll('&', '&amp;').replaceAll('<', '&lt;').replaceAll('>', '&gt;').replaceAll('"', '&quot;');
const fallback = await Promise.all(languages.map(async language => {
  const common = JSON.parse(await readFile(new URL(`locales/${language}/common.json`, shared), 'utf8'));
  return `<p lang="${language}">${escapeHtml(common.surface_render_error)}</p>`;
}));
const nextHtml = html.replace(/<!-- startup-fallback:start -->[\s\S]*?<!-- startup-fallback:end -->/, `<!-- startup-fallback:start --><section class="bootstrap-fallback" role="alert">${fallback.join('')}</section><!-- startup-fallback:end -->`);
if (nextHtml !== html) await writeFile(htmlPath, nextHtml);
